    "ky": "Негиз — 1С жүктөмөдөгү сатып алуу баасы (жана «Сатып алуу» түрү жаңыраак болсо). Жыйынтык: сатып алуу × (1 + % / 100), кабинеттегидей өйдө тегеректөө.",
