    "uz": "O‘zgarishlar avtomatik saqlanadi va darhol qo‘llanadi.",
    "ky": "Өзгөрүүлөр автоматтык сакталып, дароо колдонулат.",
    "tg": "Тағйирот худкор нигоҳ дошта мешаванд ва фавран татбиқ мешаванд.",
    "zh-CN": "更改会自动保存并立即生效。",
