  "manager.cloverAutomaticallyMakesAFullCopy": {
    "en": "Clover automatically makes a full copy on the first launch of each day, before a full reset and before restore. A safety copy is always created before restore.",
    "uz": "Clover har kuni birinchi ishga tushganda, to‘liq tiklashdan oldin va tiklashdan oldin avtomatik to‘liq nusxa yaratadi. Tiklashdan oldin doim zahira nusxa yaratiladi.",
    "ky": "Clover ар күнү биринчи иштетилгенде, толук баштапкы абалга келтирүүдөн жана калыбына келтирүүдөн мурун автоматтык толук көчүрмө түзөт. Калыбына келтирүүдөн мурун дайыма коопсуздук көчүрмөсү түзүлөт.",
    "tg": "Clover ҳар рӯз ҳангоми аввалин оғоз, пеш аз барқароркунии пурра ва пеш аз барқарорсозӣ нусхаи пурра месозад. Пеш аз барқарорсозӣ ҳамеша нусхаи эҳтиётӣ сохта мешавад.",
    "zh-CN": "Clover 会在每天首次启动、完全重置前和恢复前自动做完整备份。恢复前始终先做保险副本。",
    "ar": "ينشئ Clover نسخة كاملة تلقائياً عند أول تشغيل كل يوم وقبل إعادة التعيين الكاملة وقبل الاستعادة. تُنشأ دائماً نسخة أمان قبل الاستعادة."
  },
  "manager.cloverStoresOnlyExactMatchesAnd": {
    "en": "Clover stores only exact matches and a few closest options for unlinked products. The site name may differ from 1C: the 1C ID is sent in the order. Full nomenclature and the client base are not stored in Clover. The manager picks ambiguous matches on the Products tab.",
    "uz": "Clover faqat aniq mosliklar va bog‘lanmagan mahsulotlar uchun bir necha o‘xshash variantni saqlaydi. Saytdagi nom 1C dan farq qilishi mumkin: buyurtmaga 1C ID yuboriladi. To‘liq nomenklatura va mijozlar bazasi Clover da saqlanmaydi. Noaniq variantlarni menejer «Mahsulotlar» varag‘ida tanlaydi.",
    "ky": "Clover так дал келүүлөрдү жана байланышы жок товарлар үчүн бир нече окшош вариантты гана сактайт. Сайттагы ат 1Сден айырмаланышы мүмкүн: заказга 1С ID жөнөтүлөт. Толук номенклатура жана кардар базасы Clover’до сакталбайт. Так эмес варианттарды менеджер «Товарлар» өтмөгүнөн тандайт.",
    "tg": "Clover танҳо мувофиқати дақиқ ва чанд варианти монандро барои молҳои бепайванд нигоҳ медорад. Ном дар сайт метавонад аз 1С фарқ кунад: ба фармоиш ID-и 1С фиристода мешавад. Номенклатураи пурра ва пойгоҳи муштариён дар Clover нигоҳ дошта намешаванд. Вариантҳои норавшанро менеҷер дар варақаи «Молҳо» интихоб мекунад.",
    "zh-CN": "Clover 只保存精确匹配和未关联商品的少量近似项。网站名称可与 1C 不同：订单传送 1C ID。完整品名和客户库不保存在 Clover。歧义项由经理在“商品”页签选择。",
    "ar": "يحفظ Clover التطابقات الدقيقة وعدداً من أقرب الخيارات للمنتجات غير المرتبطة. قد يختلف اسم الموقع عن 1C: يُرسل معرف 1C في الطلب. لا تُحفظ التسمية الكاملة وقاعدة العملاء في Clover. يختار المدير الخيارات الغامضة في تبويب «المنتجات»."
  },
