    "uz": "Nusxalar mijozlar, buyurtmalar, matritsalar, sozlamalar, parollar va mahsulot fotosini o‘z ichiga oladi. Ular faqat kompyuteringizda saqlanadi.",
    "ky": "Көчүрмөлөр кардарларды, заказдарды, матрицаларды, жөндөөлөрдү, сырсөздөрдү жана товар сүрөттөрүн камтыйт. Алар сиздин компьютериңизде гана сакталат.",
    "tg": "Нусхаҳо муштариён, фармоишҳо, матрицаҳо, танзимот, паролҳо ва суратҳои молро дар бар мегиранд. Онҳо танҳо дар компютери шумо нигоҳ дошта мешаванд.",
