  "manager.createTheLoginAndPasswordYourself": {
    "en": "Create the login and password yourself — no email or confirmation. They are saved immediately in “More → Access”. Configure the matrix on the card; when the manager changes, just change the password for the same client.",
    "uz": "Login va parolni o‘zingiz yarating — xat va tasdiqsiz. Ular darhol «Yana → Kirishlar»da saqlanadi. Matritsani kartochkada sozlang; menejer almashsa, shu mijozning parolini almashtirish kifoya.",
    "ky": "Логин менен сырсөздү өзүңүз түзүңүз — катсыз жана ырастоосуз. Алар дароо «Дагы → Кирүүлөр»дө сакталат. Матрицаны карточкада жөндөңүз; менеджер алмашса, ошол кардардын сырсөзүн алмаштыруу жетиштүү.",
    "tg": "Логин ва паролро худ эҷод кунед — бе мактуб ва тасдиқ. Фавран дар «Бештар → Дастрасӣ» нигоҳ дошта мешаванд. Матрицаро дар корт танзим кунед; ҳангоми ивази менеҷер пароли ҳамон муштариро иваз кунед.",
    "zh-CN": "自行创建登录名和密码 — 无需邮件确认。会立即保存在“更多 → 访问”。在卡片上配置矩阵；更换经理时只需改同一客户的密码。",
    "ar": "أنشئ اسم الدخول وكلمة المرور بنفسك — دون رسالة أو تأكيد. يُحفظان فوراً في «المزيد → الوصول». اضبط المصفوفة في البطاقة؛ عند تغيير المدير يكفي تغيير كلمة مرور نفس العميل."
  },
