  "manager.imagesInTheRightPaneOn": {
    "en": "Images in the right pane on the home page. You can reorder, delete and upload your own. To promote a product enter an SKU or /product/… link: tapping the banner opens the card. An empty list shows the three examples again.",
    "uz": "Bosh sahifaning o‘ng oynasidagi rasmlar. Tartibni o‘zgartirish, o‘chirish va o‘zingiznikini yuklash mumkin. Mahsulotni reklama qilish uchun artikul yoki /product/… havolasini yozing: banderga bosilsa karta ochiladi. Bo‘sh ro‘yxat yana uchta namunani ko‘rsatadi.",
    "ky": "Башкы беттин оң терезесиндеги сүрөттөр. Тартипти өзгөртүп, өчүрүп, өзүңүздүкүн жүктөсөңүз болот. Товарды жарнамалоо үчүн артикул же /product/… шилтемесин жазыңыз: баннерди басса карточка ачылат. Бош тизме кайра үч мисалды көрсөтөт.",
    "tg": "Тасвирҳо дар тирезаи рости саҳифаи асосӣ. Тартибро иваз кардан, нест кардан ва худро бор кардан мумкин. Барои таблиғи мол артикул ё пайванди /product/… нависед: бо клик ба баннер корт кушода мешавад. Рӯйхати холӣ боз се мисолро нишон медиҳад.",
    "zh-CN": "首页右侧窗口的图片。可排序、删除并上传自己的。要推广商品请填货号或 /product/… 链接：点横幅打开卡片。空列表会再显示三个示例。",
    "ar": "صور في النافذة اليمنى للرئيسية. يمكن تغيير الترتيب والحذف ورفع صوركم. للترويج لمنتج أدخل الرمز أو رابط /product/… : بالضغط على البانر تُفتح البطاقة. القائمة الفارغة تعيد ثلاثة أمثلة."
  },
