  "storefront.notAnAppFromGooglePlay": {
    "en": ", not an app from Google Play. The Play Protect warning only means installation is via the browser. The official address is clover-spb.ru only; do not install copies from other sites.",
    "uz": ", Google Play dagi ilova emas. Play Protect ogohlantirishi faqat brauzer orqali o‘rnatilishini anglatadi. Rasmiy manzil — faqat clover-spb.ru; boshqa saytlardan nusxa o‘rnatmang.",
    "ky": ", Google Play’деги колдонмо эмес. Play Protect эскертүүсү орнотуу браузер аркылуу экенин гана билдирет. Расмий дарек — clover-spb.ru гана; башка сайттардан көчүрмө орнотпоңуз.",
    "tg": ", на барнома аз Google Play. Огоҳии Play Protect танҳо онро мегӯяд, ки насб тавассути браузер аст. Суроғаи расмӣ — танҳо clover-spb.ru; нусхаҳоро аз сайтҳои дигар насб накунед.",
    "zh-CN": "，不是来自 Google Play 的应用。Play Protect 警告只表示通过浏览器安装。官方地址只有 clover-spb.ru；请勿安装其他网站的副本。",
    "ar": "، وليس تطبيقاً من Google Play. تحذير Play Protect يعني فقط أن التثبيت يتم عبر المتصفح. العنوان الرسمي clover-spb.ru فقط؛ لا تثبّت نسخاً من مواقع أخرى."
  },
