  "storefront.signInToTheCabinetOrders": {
    "en": "Sign in to the portal — orders, the product matrix and delivery statuses will be at hand. Order notifications work in the installed app. The first open may take a few seconds — then it loads faster.",
    "uz": "Shaxsiy kabinetga kiring — buyurtmalar, tovar matritsasi va yetkazib berish holatlari qo‘l ostida bo‘ladi. Buyurtma bildirishnomalari o‘rnatilgan ilovada ishlaydi. Birinchi ochilish bir necha soniya olishi mumkin — keyin tezroq yuklanadi.",
    "ky": "Жеке кабинетке кириңиз — заказдар, товар матрицасы жана жеткирүү статустары колуңузда болот. Заказ билдирмелери орнотулган колдонмодо иштейт. Биринчи ачылыш бир нече секунд алышы мүмкүн — андан кийин тезирээк жүктөлөт.",
    "tg": "Ба кабинет ворид шавед — фармоишҳо, матрицаи мол ва статусҳои расонидан дар даст мешаванд. Огоҳиномаҳои фармоиш дар барномаи насбшуда кор мекунанд. Кушодани аввал метавонад чанд сония гирад — баъд барнома тезтар бор мешавад.",
    "zh-CN": "登录门户 — 订单、商品矩阵和配送状态都在手边。已安装应用可接收订单通知。首次打开可能需几秒，之后会更快。",
    "ar": "ادخل إلى البوابة — الطلبات ومصفوفة المنتجات وحالات التوصيل في متناول اليد. إشعارات الطلب تعمل في التطبيق المثبّت. قد يستغرق الفتح الأول ثوانياً — ثم يحمّل أسرع."
  },
  "storefront.specialOffersFromInformationalMaterialsNo": {
    "en": "Special offers from КЛЕВЕР. Informational materials — no automatic price changes in the catalog or cart.",
    "uz": "КЛЕВЕР kompaniyasining maxsus takliflari. Axborot materiallari — katalog va savatda narx avtomatik o‘zgarmaydi.",
    "ky": "КЛЕВЕР компаниясынын атайын сунуштары. Маалымат материалдары — каталог менен себетте баа автоматтык өзгөрбөйт.",
    "tg": "Пешниҳодҳои махсуси ширкати КЛЕВЕР. Маводи иттилоотӣ — бе тағйири худкори нарх дар каталог ва сабад.",
    "zh-CN": "КЛЕВЕР 公司特别优惠。信息内容 — 不会自动改目录和购物车价格。",
    "ar": "عروض خاصة من КЛЕВЕР. مواد معلوماتية — دون تغيير تلقائي للأسعار في الكتالوج والسلة."
  },
  "storefront.tap": {
    "en": "Tap",
    "uz": "Bosing",
    "ky": "Басыңыз",
    "tg": "Пахш кунед",
    "zh-CN": "点击",
    "ar": "اضغط"
  },
  "storefront.tapInstallOrAddTheClover": {
    "en": "Tap “Install” or “Add” — the Clover shortcut will appear among apps.",
    "uz": "«O‘rnatish» yoki «Qo‘shish»ni bosing — Clover yorlig‘i ilovalar orasida paydo bo‘ladi.",
    "ky": "«Орнотуу» же «Кошуу» басыңыз — Clover ярлыгы колдонмолордун арасында пайда болот.",
    "tg": "«Насб» ё «Илова»-ро пахш кунед — ярлиқи Clover дар байни барномаҳо пайдо мешавад.",
    "zh-CN": "点“安装”或“添加” — Clover 快捷方式会出现在应用中。",
    "ar": "اضغط «تثبيت» أو «إضافة» — سيظهر اختصار Clover بين التطبيقات."
  },
  "storefront.tapInTheTopRightAnd": {
    "en": "Tap ⋮ in the top right and choose “Install app”, “Add to Home screen” or “Install site as app”.",
    "uz": "O‘ng yuqori burchakdagi ⋮ ni bosing va «Ilovani o‘rnatish», «Asosiy ekranga qo‘shish» yoki «Saytni ilova qilib o‘rnatish»ni tanlang.",
    "ky": "Оң үстүнкү бурчтагы ⋮ басып «Колдонмону орнотуу», «Башкы экранга кошуу» же «Сайтты колдонмо кылып орнотуу» тандаңыз.",
    "tg": "⋮-ро дар кунҷи рост боло пахш кунед ва «Насб кардани барнома», «Илова ба экрани асосӣ» ё «Насб кардани сайт ҳамчун барнома»-ро интихоб кунед.",
    "zh-CN": "点右上角 ⋮，选择“安装应用”、“添加到主屏幕”或“将网站安装为应用”。",
    "ar": "اضغط ⋮ أعلى اليمين واختر «تثبيت التطبيق» أو «إضافة إلى الشاشة الرئيسية» أو «تثبيت الموقع كتطبيق»."
  },
