    "tg": "Дар сайт номи мол мисли матритсаи Clover аст (на номи хоми 1С). Аз каталоги поён интихоб ё аз 1С / Excel илова кардан мумкин, ҳатто агар позиция ҳанӯз назди ҳеҷ муштарӣ набошад.",
