export function getSeedTranslation(key, locale) {
  const row = SEEDS[key];
  if (!row) return "";
  return row[locale] || "";
}

export function listSeedKeys() {
  return Object.keys(SEEDS);
}

export function hasSeedKey(key) {
  return Object.prototype.hasOwnProperty.call(SEEDS, key);
}

for (const key of Object.keys(SEEDS)) {
  Object.freeze(SEEDS[key]);
}
Object.freeze(SEEDS);
